$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw 'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework;Add-Type -AssemblyName System.Drawing
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path,[int]$targetWidth,[int]$targetHeight){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();$dpiX=96*$targetWidth/[Math]::Max(1,$window.ActualWidth);$dpiY=96*$targetHeight/[Math]::Max(1,$window.ActualHeight);$render=New-Object Windows.Media.Imaging.RenderTargetBitmap($targetWidth,$targetHeight,$dpiX,$dpiY,[Windows.Media.PixelFormats]::Pbgra32);$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open([IO.Path]::GetFullPath($path),[IO.FileMode]::Create);try{$encoder.Save($stream)}finally{$stream.Dispose()};"${targetWidth}x${targetHeight} (WPF render)"}
function Image([int]$width,[int]$height){[HalconDotNet.HObject]$raw=$null;[HalconDotNet.HOperatorSet]::GenImageConst([ref]$raw,'byte',$width,$height);try{New-Object HalconDotNet.HImage($raw)}finally{$raw.Dispose()}}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s58-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function Tool([string]$kind,[string]$name){$main.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Run($tool){$main.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($tool,'S58 UI'))|Out-Null}
function SelectTool($tool){$raw=$tool.PSObject.BaseObject;$list=F 'FlowToolList';$list.SelectedItems.Clear();$list.SelectedItem=$raw;$main.GetMethod('FlowToolList_SelectionChanged',$private).Invoke($window,[object[]]@($list,$null))|Out-Null;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($raw))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedItem=(F 'DockParametersTaskTab');$main.GetMethod('UpdateRightTaskNavigationState',$private).Invoke($window,[object[]]@('Parameters'))|Out-Null;$main.GetMethod('RefreshUiState',$private).Invoke($window,@())|Out-Null;$main.GetMethod('FitFlowButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null}
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
$window.Topmost=$true;$window.Show();$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Left=2;$window.Top=2;$window.Width=1938;$window.Height=1158;Pump 500
$flow=F 'flowTools';$main.GetMethod('DisposeFlowTools',$private).Invoke($window,@())|Out-Null;$flow.Clear();$source=Tool ImageSource 'Inspection Input';$script=Tool CSharpDllScript 'Custom Station Logic';$text=Tool TextAssembly 'Result Message';$source.SetOutputValue('Width',[double]720);$source.SetOutputValue('Height',[double]520);$source.SetOutputValue('SN','LOT-S58');$source.SetOutputValue('ResultCode','OK');$source.ResultCode='OK';$script.SetInputBinding('NumberA',$source.ToolId,'Width');$script.SetInputBinding('String',$source.ToolId,'SN');$script.Parameters.ScriptParameterNumber=1;$script.Parameters.ScriptInlineCode='return ScriptToolResult.Ok(input.NumberA + input.ParameterNumber, "SCRIPT:" + input.Text);';$text.SetInputBinding('String',$script.ToolId,'Text');$text.Parameters.TextAssemblyTemplate='{String}';foreach($tool in @($source,$script,$text)){$flow.Add($tool)};Run $script;Run $text
$current=Image 720 520;$main.GetField('currentImage',$private).SetValue($window,$current);$main.GetField('currentImagePath',$private).SetValue($window,'S58 script workspace');(F 'viewport').SetImageSize(720,520);SelectTool $script;Pump 700
Assert($null-eq(F 'ToolCatalogSelectionDetail')) 'Permanent toolbox detail card still exists';Assert((F 'DockScriptPanel').Visibility.ToString()-eq'Visible') 'Script task panel is not contextual';Assert(-not(F 'DockScriptEditorExpander').IsExpanded) 'Script editor should be collapsed by default';$wide=Shot $WideOutputPath 1938 1158
$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Width=1366;$window.Height=768;$window.Left=2;$window.Top=2;SelectTool $script;Pump 700;Assert((F 'ToolCatalogPanel').ActualWidth-gt0-and(F 'FlowWorkspacePanel').ActualWidth-gt0-and(F 'RightTabs').ActualWidth-gt0) 'Core workspace regions are not visible at 1366x768';Assert(-not(F 'DockScriptEditorExpander').IsExpanded) 'Compact editor should remain collapsed';$compact=Shot $CompactOutputPath 1366 768
$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output "S58_UI_CAPTURE=PASS; Wide=$WideOutputPath; Compact=$CompactOutputPath; WideSize=$wide; CompactSize=$compact; PermanentToolDetail=0; ScriptEditorDefaultExpanded=0"
